import { ANATOMY, BASE_ROTATIONS, RIGGING } from '../constants';
import { PartName, Pose, Vector2D, JointConstraint } from '../types';

export const lerp = (start: number, end: number, t: number): number => start * (1 - t) + end * t;

export const getShortestAngleDiffDeg = (currentDeg: number, startDeg: number): number => {
  let diff = currentDeg - startDeg;
  diff = ((diff % 360) + 360) % 360; 
  if (diff > 180) diff -= 360;
  return diff;
};

const rad = (deg: number): number => deg * Math.PI / 180;
const deg = (rad: number): number => rad * 180 / Math.PI;
const rotateVec = (x: number, y: number, angleDeg: number): Vector2D => {
  const r = rad(angleDeg);
  const c = Math.cos(r);
  const s = Math.sin(r);
  return { x: x * c - y * s, y: x * s + y * c };
};
const addVec = (v1: Vector2D, v2: Vector2D): Vector2D => ({ x: v1.x + v2.x, y: v1.y + v2.y });

export const getTotalRotation = (key: string, pose: Pose): number => (BASE_ROTATIONS[key as keyof typeof BASE_ROTATIONS] || 0) + ((pose as any)[key] || 0);

const calculateBoneGlobalPositions = (
  parentGlobalPos: Vector2D,
  parentGlobalAngle: number,
  boneTotalLocalRotation: number,
  boneLength: number,
  boneOffset: Vector2D = { x: 0, y: 0 },
  isUpwardDrawing: boolean = false
): { globalStartPoint: Vector2D; globalEndPoint: Vector2D; childInheritedGlobalAngle: number } => {
  const rotatedOffset = rotateVec(boneOffset.x, boneOffset.y, parentGlobalAngle);
  const globalStartPoint = addVec(parentGlobalPos, rotatedOffset);
  const boneGlobalAngleForItsBody = parentGlobalAngle + boneTotalLocalRotation;
  const y_direction = isUpwardDrawing ? -1 : 1;
  const boneVector = rotateVec(0, boneLength * y_direction, boneGlobalAngleForItsBody);
  const globalEndPoint = addVec(globalStartPoint, boneVector);
  const childInheritedGlobalAngle = parentGlobalAngle + boneTotalLocalRotation;
  return { globalStartPoint, globalEndPoint, childInheritedGlobalAngle };
};

export const getJointPositions = (pose: Pose, jointModes: Record<PartName, JointConstraint> = {} as any) => {
  const { root } = pose;
  const offsets = pose.offsets || {};
  const bodyRotation = getTotalRotation('bodyRotation', pose);

  // CORE HIERARCHY: Waist -> Torso -> Collar -> Head
  const waistCalc = calculateBoneGlobalPositions(root, bodyRotation, getTotalRotation(PartName.Waist, pose), ANATOMY.WAIST, offsets[PartName.Waist], true);
  const torsoCalc = calculateBoneGlobalPositions(waistCalc.globalEndPoint, waistCalc.childInheritedGlobalAngle, getTotalRotation(PartName.Torso, pose), ANATOMY.TORSO, offsets[PartName.Torso], true);
  const collarCalc = calculateBoneGlobalPositions(torsoCalc.globalEndPoint, torsoCalc.childInheritedGlobalAngle, getTotalRotation(PartName.Collar, pose), ANATOMY.COLLAR, offsets[PartName.Collar], true);

  const collarChildAngle = collarCalc.childInheritedGlobalAngle;
  const collarBase = collarCalc.globalStartPoint; 

  // HEAD attaches to collar end (tip)
  const headGapOffset = rotateVec(0, -ANATOMY.HEAD_NECK_GAP_OFFSET, collarChildAngle);
  const headPivot = addVec(collarCalc.globalEndPoint, headGapOffset);
  const headGlobalAngle = collarChildAngle + getTotalRotation(PartName.Head, pose);
  const headTip = addVec(headPivot, rotateVec(0, -ANATOMY.HEAD, headGlobalAngle));

  const getArmJoints = (isRight: boolean) => {
    const sKey = isRight ? PartName.RShoulder : PartName.LShoulder;
    const shoulderAttachX = isRight ? RIGGING.R_SHOULDER_X_OFFSET : RIGGING.L_SHOULDER_X_OFFSET;

    // REDESIGN: Arms always stay at the corners of the collar. 
    // They are rotated by the collar's absolute angle (collarChildAngle).
    const shoulderAttach = addVec(collarBase, rotateVec(shoulderAttachX, RIGGING.SHOULDER_Y_OFFSET_FROM_BASE, collarChildAngle));

    const upperArmCalc = calculateBoneGlobalPositions(shoulderAttach, collarChildAngle, getTotalRotation(sKey, pose), ANATOMY.UPPER_ARM, offsets[sKey], false);
    const forearmCalc = calculateBoneGlobalPositions(upperArmCalc.globalEndPoint, upperArmCalc.childInheritedGlobalAngle, getTotalRotation(isRight ? 'rForearm' : 'lForearm', pose), ANATOMY.LOWER_ARM, offsets[isRight ? PartName.RElbow : PartName.LElbow], false);
    const handGlobalAngle = forearmCalc.childInheritedGlobalAngle + getTotalRotation(isRight ? PartName.RWrist : PartName.LWrist, pose);
    const handTip = addVec(forearmCalc.globalEndPoint, rotateVec(0, ANATOMY.HAND, handGlobalAngle));
    return { shoulder: shoulderAttach, elbow: upperArmCalc.globalEndPoint, wrist: forearmCalc.globalEndPoint, hand: handTip };
  };

  const getLegJoints = (isRight: boolean) => {
    const tKey = isRight ? PartName.RThigh : PartName.LThigh;
    const thighCalc = calculateBoneGlobalPositions(root, bodyRotation, getTotalRotation(tKey, pose), ANATOMY.LEG_UPPER, offsets[tKey], false);
    const calfCalc = calculateBoneGlobalPositions(thighCalc.globalEndPoint, thighCalc.childInheritedGlobalAngle, getTotalRotation(isRight ? 'rCalf' : 'lCalf', pose), ANATOMY.LEG_LOWER, offsets[isRight ? PartName.RSkin : PartName.LSkin], false);
    const ankleGlobalAngle = calfCalc.childInheritedGlobalAngle + getTotalRotation(isRight ? PartName.RAnkle : PartName.LAnkle, pose);
    const footTip = addVec(calfCalc.globalEndPoint, rotateVec(0, ANATOMY.FOOT, ankleGlobalAngle));
    return { hip: root, knee: thighCalc.globalEndPoint, ankle: calfCalc.globalEndPoint, footTip };
  };

  const rArm = getArmJoints(true);
  const lArm = getArmJoints(false);
  const rLeg = getLegJoints(true);
  const lLeg = getLegJoints(false);

  return {
    root,
    waist: root,
    torso: waistCalc.globalEndPoint,
    collar: torsoCalc.globalEndPoint,
    head: headPivot,
    rShoulder: rArm.shoulder,
    rElbow: rArm.elbow,
    rWrist: rArm.wrist,
    lShoulder: lArm.shoulder,
    lElbow: lArm.elbow,
    lWrist: lArm.wrist,
    rThigh: root,
    [PartName.RSkin]: rLeg.knee,
    rAnkle: rLeg.ankle,
    lThigh: root,
    [PartName.LSkin]: lLeg.knee,
    lAnkle: lLeg.ankle,
    headTip,
    rFootTip: rLeg.footTip,
    lFootTip: lLeg.footTip,
    rHandTip: rArm.hand,
    lHandTip: lArm.hand,
  };
};

export const getPartGlobalAngles = (pose: Pose) => {
  const angles: { [key: string]: number } = {};
  const bodyRotation = getTotalRotation('bodyRotation', pose);
  const waistGlobal = bodyRotation + getTotalRotation(PartName.Waist, pose);
  const torsoGlobal = waistGlobal + getTotalRotation(PartName.Torso, pose);
  const collarGlobal = torsoGlobal + getTotalRotation(PartName.Collar, pose);
  angles[PartName.Waist] = waistGlobal;
  angles[PartName.Torso] = torsoGlobal;
  angles[PartName.Collar] = collarGlobal;
  angles[PartName.Head] = collarGlobal + getTotalRotation(PartName.Head, pose);

  const processArm = (isRight: boolean) => {
    const sKey = isRight ? PartName.RShoulder : PartName.LShoulder;
    const fKey = isRight ? 'rForearm' : 'lForearm';
    const wKey = isRight ? PartName.RWrist : PartName.LWrist;
    const sAngle = collarGlobal + getTotalRotation(sKey, pose);
    const fAngle = sAngle + getTotalRotation(fKey, pose);
    const wAngle = fAngle + getTotalRotation(wKey, pose);
    angles[sKey] = sAngle;
    angles[isRight ? PartName.RElbow : PartName.LElbow] = fAngle;
    angles[wKey] = wAngle;
  };
  processArm(true);
  processArm(false);

  const processLeg = (isRight: boolean) => {
    const tKey = isRight ? PartName.RThigh : PartName.LThigh;
    const cKey = isRight ? 'rCalf' : 'lCalf';
    const aKey = isRight ? PartName.RAnkle : PartName.LAnkle;
    const tAngle = bodyRotation + getTotalRotation(tKey, pose);
    const cAngle = tAngle + getTotalRotation(cKey, pose);
    const aAngle = cAngle + getTotalRotation(aKey, pose);
    angles[tKey] = tAngle;
    angles[isRight ? PartName.RSkin : PartName.LSkin] = cAngle;
    angles[aKey] = aAngle;
  };
  processLeg(true);
  processLeg(false);

  return angles;
};

export const solveArmIK = (target: Vector2D, isRight: boolean, pose: Pose, jointModes: Record<PartName, JointConstraint> = {} as any) => {
  const joints = getJointPositions(pose, jointModes);
  const sPos = isRight ? joints.rShoulder : joints.lShoulder;
  const l1 = ANATOMY.UPPER_ARM;
  const l2 = ANATOMY.LOWER_ARM;
  const dx = target.x - sPos.x;
  const dy = target.y - sPos.y;
  const distSq = dx * dx + dy * dy;
  const dist = Math.sqrt(distSq);
  const MAX_ARM_DIST = l1 + l2 + 5;
  if (dist > MAX_ARM_DIST || dist < Math.abs(l1 - l2)) return null; 

  const angleToTarget = Math.atan2(dy, dx);
  const sAngleTri = Math.acos((l1 * l1 + distSq - l2 * l2) / (2 * l1 * dist));
  const eAngleTri = Math.acos((l1 * l1 + l2 * l2 - distSq) / (2 * l1 * l2));

  const sGlobal = angleToTarget - sAngleTri;
  const fLocal = Math.PI - eAngleTri; 

  const collarAngle = getPartGlobalAngles(pose)[PartName.Collar];
  return {
    shoulder: deg(sGlobal) - collarAngle - BASE_ROTATIONS[isRight ? PartName.RShoulder : PartName.LShoulder],
    forearm: deg(fLocal) - BASE_ROTATIONS[isRight ? 'rForearm' : 'lForearm']
  };
};

export const solveLegIK = (target: Vector2D, isRight: boolean, pose: Pose, jointModes: Record<PartName, JointConstraint> = {} as any) => {
  const joints = getJointPositions(pose, jointModes);
  const hPos = isRight ? joints.rThigh : joints.lThigh;
  const l1 = ANATOMY.LEG_UPPER;
  const l2 = ANATOMY.LEG_LOWER;
  const dx = target.x - hPos.x;
  const dy = target.y - hPos.y;
  const distSq = dx * dx + dy * dy;
  const dist = Math.sqrt(distSq);
  const MAX_LEG_DIST = l1 + l2 + 5;
  if (dist > MAX_LEG_DIST || dist < Math.abs(l1 - l2)) return null; 

  const angleToTarget = Math.atan2(dy, dx);
  const tAngleTri = Math.acos((l1 * l1 + distSq - l2 * l2) / (2 * l1 * dist));
  const kAngleTri = Math.acos((l1 * l1 + l2 * l2 - distSq) / (2 * l1 * l2));

  const tGlobal = angleToTarget - tAngleTri;
  const cLocal = Math.PI - kAngleTri; 

  const bodyRot = getTotalRotation('bodyRotation', pose);
  return {
    thigh: deg(tGlobal) - bodyRot - BASE_ROTATIONS[isRight ? PartName.RThigh : PartName.LThigh],
    calf: deg(cLocal) - BASE_ROTATIONS[isRight ? 'rCalf' : 'lCalf']
  };
};

import React from 'react';
import { Bone, type BoneProps } from './Bone'; 
import { ANATOMY, RIGGING } from '../constants';
import { getJointPositions, getTotalRotation } from '../utils/kinematics';
import { PartName, PartSelection, PartVisibility, AnchorName, Pose, JointConstraint, RenderMode, PARENT_MAP, partNameToPoseKey } from '../types';
import { COLORS_BY_CATEGORY } from './Bone'; 

interface MannequinProps {
  pose: Pose;
  showOverlay?: boolean;
  selectedParts: PartSelection;
  visibility: PartVisibility;
  pin: AnchorName;
  className?: string;
  onMouseDownOnPart?: (part: PartName, event: React.MouseEvent<SVGGElement>) => void;
  onHoverOnPart?: (part: PartName) => void;
  onDoubleClickOnPart?: (part: PartName, event: React.MouseEvent<SVGGElement>) => void; 
  onTripleClickOnPart?: (part: PartName) => void;
  onMouseDownOnRoot?: (event: React.MouseEvent<SVGCircleElement>) => void;
  isAirMode: boolean;
  showHighlights?: boolean;
  onToggleCrane: () => void;
  isCraneActive: boolean;
  jointModes: Record<PartName, JointConstraint>; 
  renderMode?: RenderMode; 
  bodyRotation: number; 
}

export const getPartCategory = (part: PartName): string => { 
  switch (part) {
    case PartName.RWrist:
    case PartName.LWrist: return 'hand';
    case PartName.RElbow: 
    case PartName.LElbow: return 'forearm';
    case PartName.RShoulder: 
    case PartName.LShoulder: return 'bicep';
    case PartName.Collar: return 'collar';
    case PartName.Torso: return 'torso';
    case PartName.Waist: return 'waist';
    case PartName.RThigh:
    case PartName.LThigh: return 'thigh';
    case PartName.RSkin: 
    case PartName.LSkin: return 'shin';
    case PartName.RAnkle: 
    case PartName.LAnkle: return 'foot';
    case PartName.Head: return 'head';
    default: return 'default';
  }
};

export const Mannequin: React.FC<MannequinProps> = ({
  pose,
  showOverlay = true,
  selectedParts,
  visibility,
  pin,
  className = "text-ink",
  onMouseDownOnPart,
  onHoverOnPart,
  onDoubleClickOnPart,
  onTripleClickOnPart,
  onMouseDownOnRoot,
  showHighlights = true,
  onToggleCrane,
  isCraneActive,
  jointModes, 
  renderMode = 'default', 
  bodyRotation, 
}) => {
  const joints = getJointPositions(pose, jointModes);
  const offsets = pose.offsets || {};

  const isRightLimb = (part: PartName) => ['rShoulder', 'rElbow', 'rWrist', 'rThigh', 'rSkin', 'rAnkle'].includes(part);
  const isLeftLimb = (part: PartName) => ['lShoulder', 'lElbow', 'lWrist', 'lThigh', 'lSkin', 'lAnkle'].includes(part);

  const PartWrapper = ({ part, children }: { part: PartName; children?: React.ReactNode }) => {
    const isSelected = selectedParts[part];
    const selectionClass = isSelected && showHighlights ? 'text-selection' : '';

    const handleMouseDown = (e: React.MouseEvent<SVGGElement>) => { 
      e.stopPropagation(); 
      if (e.detail === 3) onTripleClickOnPart?.(part);
      else onMouseDownOnPart?.(part, e); 
    };

    const handleMouseEnter = (e: React.MouseEvent<SVGGElement>) => { e.stopPropagation(); onHoverOnPart?.(part); };
    const handleDoubleClick = (e: React.MouseEvent<SVGGElement>) => { e.stopPropagation(); onDoubleClickOnPart?.(part, e); }; 

    let darken20Percent = false;
    if (bodyRotation > 0 && bodyRotation <= 180 && isRightLimb(part)) {
      darken20Percent = true;
    }
    else if (bodyRotation < 0 && bodyRotation >= -180 && isLeftLimb(part)) {
      darken20Percent = true;
    }

    return (
      <g className={`cursor-pointer ${selectionClass}`} onMouseDown={handleMouseDown} onMouseEnter={handleMouseEnter} onDoubleClick={handleDoubleClick}>
        {React.Children.map(children, child =>
          React.isValidElement(child) && child.type === Bone
            ? React.cloneElement(child as React.ReactElement<BoneProps>, { darken20Percent: darken20Percent })
            : child
        )}
      </g>
    );
  };

  const ROOT_COLOR = "#708238"; 
  const PIN_INDICATOR_SIZE = ANATOMY.ROOT_SIZE * 0.7; 
  const PIN_INDICATOR_STROKE_COLOR = "#D1D5DB";
  const PIN_INDICATOR_STROKE_WIDTH = 1;

  const collarRotation = getTotalRotation(PartName.Collar, pose);

  return (
    <g className={`mannequin-root ${className}`} transform={`translate(${pose.root.x}, ${pose.root.y}) rotate(${bodyRotation})`}>
      <g 
        onMouseDown={onMouseDownOnRoot} 
        onDoubleClick={(e) => { e.stopPropagation(); onToggleCrane(); }} 
        className={isCraneActive ? 'cursor-ns-resize' : 'cursor-pointer'} 
        data-no-export={true}
      >
        <circle cx="0" cy="0" r={ANATOMY.ROOT_SIZE} fill="currentColor" opacity="0.1" />
        <circle 
          cx="0" cy="0" r={PIN_INDICATOR_SIZE} 
          fill={(isCraneActive || pin === 'root') ? COLORS_BY_CATEGORY.bicep : ROOT_COLOR} 
          stroke={PIN_INDICATOR_STROKE_COLOR} 
          strokeWidth={PIN_INDICATOR_STROKE_WIDTH} 
        />
      </g>

      {renderMode === 'wireframe' && Object.values(PartName).map(childPart => {
        const parentPart = PARENT_MAP[childPart];
        const childJoint = joints[childPart];
        let parentJoint;
        if (childPart === PartName.Waist || childPart === PartName.RThigh || childPart === PartName.LThigh) {
            parentJoint = joints.root;
        } else if (parentPart) {
            parentJoint = joints[parentPart];
        }
        if (parentJoint && childJoint) {
          return (
            <line 
              key={`conn-${parentPart}-${childPart}`}
              x1={parentJoint.x - pose.root.x}
              y1={parentJoint.y - pose.root.y}
              x2={childJoint.x - pose.root.x}
              y2={childJoint.y - pose.root.y}
              stroke={'#9CA3AF'} 
              strokeWidth="2"
              opacity="0.5"
            />
          );
        }
        return null;
      })}

      {pin !== 'root' && joints[pin as keyof typeof joints] && (
        <g transform={`translate(${joints[pin as keyof typeof joints].x - pose.root.x}, ${joints[pin as keyof typeof joints].y - pose.root.y})`} data-no-export={true}>
          <circle cx="0" cy="0" r={ANATOMY.ROOT_SIZE} fill="currentColor" opacity="0.1" />
          <circle 
            cx="0" cy="0" r={PIN_INDICATOR_SIZE} 
            fill={isCraneActive ? COLORS_BY_CATEGORY.bicep : ROOT_COLOR}
            stroke={PIN_INDICATOR_STROKE_COLOR} 
            strokeWidth={PIN_INDICATOR_STROKE_WIDTH} 
          />
        </g>
      )}

      <PartWrapper part={PartName.Waist}>
        <Bone 
          isSelected={selectedParts[PartName.Waist]} 
          constraint={jointModes[PartName.Waist]} 
          rotation={getTotalRotation(PartName.Waist, pose)} 
          length={ANATOMY.WAIST} 
          width={ANATOMY.WAIST_WIDTH} 
          variant="waist-teardrop-pointy-up" 
          drawsUpwards 
          showOverlay={showOverlay} 
          offset={offsets[PartName.Waist]} 
          visible={visibility[PartName.Waist]} 
          partCategory={getPartCategory(PartName.Waist)}
          renderMode={renderMode}
        >
          <PartWrapper part={PartName.Torso}>
            <Bone 
              isSelected={selectedParts[PartName.Torso]} 
              constraint={jointModes[PartName.Torso]} 
              rotation={getTotalRotation(PartName.Torso, pose)} 
              length={ANATOMY.TORSO} 
              width={ANATOMY.TORSO_WIDTH} 
              variant="torso-teardrop-pointy-down" 
              drawsUpwards 
              showOverlay={showOverlay} 
              offset={offsets[PartName.Torso]} 
              visible={visibility[PartName.Torso]} 
              partCategory={getPartCategory(PartName.Torso)}
              renderMode={renderMode}
            >
              <PartWrapper part={PartName.Collar}>
                <g>
                  {/* COLLAR BONE */}
                  <Bone 
                    isSelected={selectedParts[PartName.Collar]} 
                    constraint={jointModes[PartName.Collar]} 
                    rotation={collarRotation} 
                    length={ANATOMY.COLLAR} 
                    width={ANATOMY.COLLAR_WIDTH} 
                    variant="collar-horizontal-oval-shape" 
                    drawsUpwards 
                    showOverlay={showOverlay} 
                    partCategory={getPartCategory(PartName.Collar)}
                    offset={offsets[PartName.Collar]} 
                    visible={visibility[PartName.Collar]} 
                    renderMode={renderMode}
                  >
                    <PartWrapper part={PartName.Head}>
                      <Bone 
                        isSelected={selectedParts[PartName.Head]} 
                        constraint={jointModes[PartName.Head]} 
                        rotation={getTotalRotation(PartName.Head, pose)} 
                        length={ANATOMY.HEAD} 
                        width={ANATOMY.HEAD_WIDTH} 
                        variant="head-tall-oval" 
                        drawsUpwards 
                        showOverlay={showOverlay} 
                        offset={offsets[PartName.Head]} 
                        visible={visibility[PartName.Head]} 
                        partCategory={getPartCategory(PartName.Head)}
                        renderMode={renderMode}
                      />
                    </PartWrapper>
                  </Bone>

                  {/* RIGHT SHOULDER: Tethered to corner of collar. In Torso Tip space, rotate by CollarLocal then translate. */}
                  <g transform={`rotate(${collarRotation}) translate(${RIGGING.R_SHOULDER_X_OFFSET}, ${RIGGING.SHOULDER_Y_OFFSET_FROM_BASE})`}>
                    <PartWrapper part={PartName.RShoulder}>
                      <Bone 
                        isSelected={selectedParts[PartName.RShoulder]} 
                        constraint={jointModes[PartName.RShoulder]} 
                        rotation={getTotalRotation(PartName.RShoulder, pose)} 
                        length={ANATOMY.UPPER_ARM} 
                        width={ANATOMY.LIMB_WIDTH_ARM} 
                        variant="deltoid-shape" 
                        showOverlay={showOverlay} 
                        offset={offsets[PartName.RShoulder]} 
                        visible={visibility[PartName.RShoulder]} 
                        partCategory={getPartCategory(PartName.RShoulder)}
                        renderMode={renderMode}
                      >
                        <PartWrapper part={PartName.RElbow}>
                          <Bone 
                            isSelected={selectedParts[PartName.RElbow]} 
                            constraint={jointModes[PartName.RElbow]} 
                            rotation={getTotalRotation('rForearm', pose)} 
                            length={ANATOMY.LOWER_ARM} 
                            width={ANATOMY.LIMB_WIDTH_FOREARM} 
                            variant="limb-tapered" 
                            showOverlay={showOverlay} 
                            offset={offsets[PartName.RElbow]} 
                            visible={visibility[PartName.RElbow]} 
                            partCategory={getPartCategory(PartName.RElbow)}
                            renderMode={renderMode}
                          >
                            <PartWrapper part={PartName.RWrist}>
                              <Bone 
                                isSelected={selectedParts[PartName.RWrist]} 
                                constraint={jointModes[PartName.RWrist]} 
                                rotation={getTotalRotation(PartName.RWrist, pose)} 
                                length={ANATOMY.HAND} 
                                width={ANATOMY.HAND_WIDTH} 
                                variant="hand-foot-arrowhead-shape" 
                                showOverlay={showOverlay} 
                                offset={offsets[PartName.RWrist]} 
                                visible={visibility[PartName.RWrist]} 
                                partCategory={getPartCategory(PartName.RWrist)}
                                renderMode={renderMode}
                              />
                            </PartWrapper>
                          </Bone>
                        </PartWrapper>
                      </Bone>
                    </PartWrapper>
                  </g>

                  {/* LEFT SHOULDER: Tethered to corner of collar. In Torso Tip space, rotate by CollarLocal then translate. */}
                  <g transform={`rotate(${collarRotation}) translate(${RIGGING.L_SHOULDER_X_OFFSET}, ${RIGGING.SHOULDER_Y_OFFSET_FROM_BASE})`}>
                    <PartWrapper part={PartName.LShoulder}>
                      <Bone 
                        isSelected={selectedParts[PartName.LShoulder]} 
                        constraint={jointModes[PartName.LShoulder]} 
                        rotation={getTotalRotation(PartName.LShoulder, pose)} 
                        length={ANATOMY.UPPER_ARM} 
                        width={ANATOMY.LIMB_WIDTH_ARM} 
                        variant="deltoid-shape" 
                        showOverlay={showOverlay} 
                        offset={offsets[PartName.LShoulder]} 
                        visible={visibility[PartName.LShoulder]} 
                        partCategory={getPartCategory(PartName.LShoulder)}
                        renderMode={renderMode}
                      >
                        <PartWrapper part={PartName.LElbow}>
                          <Bone 
                            isSelected={selectedParts[PartName.LElbow]} 
                            constraint={jointModes[PartName.LElbow]} 
                            rotation={getTotalRotation('lForearm', pose)} 
                            length={ANATOMY.LOWER_ARM} 
                            width={ANATOMY.LIMB_WIDTH_FOREARM} 
                            variant="limb-tapered" 
                            showOverlay={showOverlay} 
                            offset={offsets[PartName.LElbow]} 
                            visible={visibility[PartName.LElbow]} 
                            partCategory={getPartCategory(PartName.LElbow)}
                            renderMode={renderMode}
                          >
                            <PartWrapper part={PartName.LWrist}>
                              <Bone 
                                isSelected={selectedParts[PartName.LWrist]} 
                                constraint={jointModes[PartName.LWrist]} 
                                rotation={getTotalRotation(PartName.LWrist, pose)} 
                                length={ANATOMY.HAND} 
                                width={ANATOMY.HAND_WIDTH} 
                                variant="hand-foot-arrowhead-shape" 
                                showOverlay={showOverlay} 
                                offset={offsets[PartName.LWrist]} 
                                visible={visibility[PartName.LWrist]} 
                                partCategory={getPartCategory(PartName.LWrist)}
                                renderMode={renderMode}
                              />
                            </PartWrapper>
                          </Bone>
                        </PartWrapper>
                      </Bone>
                    </PartWrapper>
                  </g>
                </g>
              </PartWrapper>
            </Bone>
          </PartWrapper>
        </Bone>
      </PartWrapper>

      <PartWrapper part={PartName.RThigh}>
        <Bone 
          isSelected={selectedParts[PartName.RThigh]} 
          constraint={jointModes[PartName.RThigh]} 
          rotation={getTotalRotation(PartName.RThigh, pose)} 
          length={ANATOMY.LEG_UPPER} 
