  torso: 0,
  waist: 0,
  collar: 0,
  head: 0,
  lShoulder: 0, 
  lForearm: 0,
  lWrist: 0,
  rShoulder: 0, 
  rForearm: 0,
  rWrist: 0,
  lThigh: 0,
  lCalf: 0,
  lAnkle: 0,
  rThigh: 0,
  rCalf: 0,
  rAnkle: 0,
