import React from 'react';
import { Bone, type BoneProps } from './Bone'; 
import { ANATOMY, RIGGING } from '../constants';
import { getJointPositions, getTotalRotation } from '../utils/kinematics';
import { PartName, PartSelection, PartVisibility, AnchorName, Pose, JointConstraint, RenderMode, PARENT_MAP, partNameToPoseKey } from '../types';
import { COLORS_BY_CATEGORY } from './Bone'; 

interface MannequinProps {
  pose: Pose;
  showOverlay?: boolean;
  selectedParts: PartSelection;
  visibility: PartVisibility;
  pin: AnchorName;
  className?: string;
  onMouseDownOnPart?: (part: PartName, event: React.MouseEvent<SVGGElement>) => void;
  onHoverOnPart?: (part: PartName) => void;
  onDoubleClickOnPart?: (part: PartName, event: React.MouseEvent<SVGGElement>) => void; 
  onTripleClickOnPart?: (part: PartName) => void;
  onMouseDownOnRoot?: (event: React.MouseEvent<SVGCircleElement>) => void;
  isAirMode: boolean;
  showHighlights?: boolean;
  onToggleCrane: () => void;
  isCraneActive: boolean;
  jointModes: Record<PartName, JointConstraint>; 
  renderMode?: RenderMode; 
  bodyRotation: number; 
}

export const getPartCategory = (part: PartName): string => { 
  switch (part) {
    case PartName.RWrist:
    case PartName.LWrist: return 'hand';
    case PartName.RElbow: 
    case PartName.LElbow: return 'forearm';
    case PartName.RShoulder: 
    case PartName.LShoulder: return 'bicep';
    case PartName.Collar: return 'collar';
    case PartName.Torso: return 'torso';
    case PartName.Waist: return 'waist';
    case PartName.RThigh:
    case PartName.LThigh: return 'thigh';
    case PartName.RSkin: 
    case PartName.LSkin: return 'shin';
    case PartName.RAnkle: 
    case PartName.LAnkle: return 'foot';
    case PartName.Head: return 'head';
    default: return 'default';
  }
};

export const Mannequin: React.FC<MannequinProps> = ({
  pose,
  showOverlay = true,
  selectedParts,
  visibility,
  pin,
  className = "text-ink",
  onMouseDownOnPart,
  onHoverOnPart,
  onDoubleClickOnPart,
  onTripleClickOnPart,
  onMouseDownOnRoot,
  showHighlights = true,
  onToggleCrane,
  isCraneActive,
  jointModes, 
  renderMode = 'default', 
  bodyRotation, 
}) => {
  const joints = getJointPositions(pose, jointModes);
  const offsets = pose.offsets || {};

  const isRightLimb = (part: PartName) => ['rShoulder', 'rElbow', 'rWrist', 'rThigh', 'rSkin', 'rAnkle'].includes(part);
  const isLeftLimb = (part: PartName) => ['lShoulder', 'lElbow', 'lWrist', 'lThigh', 'lSkin', 'lAnkle'].includes(part);

  const PartWrapper = ({ part, children }: { part: PartName; children?: React.ReactNode }) => {
    const isSelected = selectedParts[part];
    const selectionClass = isSelected && showHighlights ? 'text-selection' : '';

    const handleMouseDown = (e: React.MouseEvent<SVGGElement>) => { 
      e.stopPropagation(); 
      if (e.detail === 3) onTripleClickOnPart?.(part);
      else onMouseDownOnPart?.(part, e); 
    };

    const handleMouseEnter = (e: React.MouseEvent<SVGGElement>) => { e.stopPropagation(); onHoverOnPart?.(part); };
    const handleDoubleClick = (e: React.MouseEvent<SVGGElement>) => { e.stopPropagation(); onDoubleClickOnPart?.(part, e); }; 

    let darken20Percent = false;
    if (bodyRotation > 0 && bodyRotation <= 180 && isRightLimb(part)) darken20Percent = true;
    else if (bodyRotation < 0 && bodyRotation >= -180 && isLeftLimb(part)) darken20Percent = true;

    return (
      <g className={`cursor-pointer ${selectionClass}`} onMouseDown={handleMouseDown} onMouseEnter={handleMouseEnter} onDoubleClick={handleDoubleClick}>
        {React.Children.map(children, child =>
          React.isValidElement(child) && child.type === Bone
            ? React.cloneElement(child as React.ReactElement<BoneProps>, { darken20Percent: darken20Percent })
            : child
        )}
      </g>
    );
  };

  const ANCHOR_RED = "#F87171"; 
  const collarRotation = getTotalRotation(PartName.Collar, pose);

  // YAW-BASED LAYERING LOGIC
  const isNeutralFront = Math.abs(bodyRotation) < 0.1;
  const isRotatingRight = bodyRotation > 0; // Looking right, Left Arm is Front

  const renderArm = (isRight: boolean) => {
    const sKey = isRight ? PartName.RShoulder : PartName.LShoulder;
    const eKey = isRight ? PartName.RElbow : PartName.LElbow;
    const wKey = isRight ? PartName.RWrist : PartName.LWrist;
    const xOff = isRight ? RIGGING.R_SHOULDER_X_OFFSET : RIGGING.L_SHOULDER_X_OFFSET;

    return (
      <g transform={`translate(${joints.collar.x - pose.root.x}, ${joints.collar.y - pose.root.y})`}>
        <g transform={`rotate(${collarRotation}) translate(${xOff}, ${RIGGING.SHOULDER_Y_OFFSET_FROM_BASE})`}>
          <PartWrapper part={sKey}>
            <Bone 
              isSelected={selectedParts[sKey]} 
              constraint={jointModes[sKey]} 
              rotation={getTotalRotation(sKey, pose)} 
              length={ANATOMY.UPPER_ARM} width={ANATOMY.LIMB_WIDTH_ARM} 
              variant="deltoid-shape" showOverlay={showOverlay} 
              offset={offsets[sKey]} visible={visibility[sKey]} 
              partCategory={getPartCategory(sKey)} renderMode={renderMode}
            >
              <PartWrapper part={eKey}>
                <Bone 
                  isSelected={selectedParts[eKey]} 
                  constraint={jointModes[eKey]} 
                  rotation={getTotalRotation(isRight ? 'rForearm' : 'lForearm', pose)} 
                  length={ANATOMY.LOWER_ARM} width={ANATOMY.LIMB_WIDTH_FOREARM} 
                  variant="limb-tapered" showOverlay={showOverlay} 
                  offset={offsets[eKey]} visible={visibility[eKey]} 
                  partCategory={getPartCategory(eKey)} renderMode={renderMode}
                >
                  <PartWrapper part={wKey}>
                    <Bone 
                      isSelected={selectedParts[wKey]} 
                      constraint={jointModes[wKey]} 
                      rotation={getTotalRotation(wKey, pose)} 
                      length={ANATOMY.HAND} width={ANATOMY.HAND_WIDTH} 
                      variant="hand-foot-arrowhead-shape" showOverlay={showOverlay} 
                      offset={offsets[wKey]} visible={visibility[wKey]} 
                      partCategory={getPartCategory(wKey)} renderMode={renderMode}
                    />
                  </PartWrapper>
                </Bone>
              </PartWrapper>
            </Bone>
          </PartWrapper>
        </g>
      </g>
    );
  };

  const renderLeg = (isRight: boolean) => {
    const tKey = isRight ? PartName.RThigh : PartName.LThigh;
    const sKey = isRight ? PartName.RSkin : PartName.LSkin;
    const aKey = isRight ? PartName.RAnkle : PartName.LAnkle;
    const hipX = isRight ? RIGGING.WAIST_ANCHOR_MID_X : -RIGGING.WAIST_ANCHOR_MID_X;

    return (
      <g transform={`translate(${hipX}, 0)`}>
        <PartWrapper part={tKey}>
          <Bone 
            isSelected={selectedParts[tKey]} 
            constraint={jointModes[tKey]} 
            rotation={getTotalRotation(tKey, pose)} 
            length={ANATOMY.LEG_UPPER} width={ANATOMY.LIMB_WIDTH_THIGH} 
            variant="limb-tapered" showOverlay={showOverlay} 
            offset={offsets[tKey]} visible={visibility[tKey]} 
            partCategory={getPartCategory(tKey)} renderMode={renderMode}
          >
            <PartWrapper part={sKey}>
              <Bone 
                isSelected={selectedParts[sKey]} 
                constraint={jointModes[sKey]} 
                rotation={getTotalRotation(isRight ? 'rCalf' : 'lCalf', pose)} 
                length={ANATOMY.LEG_LOWER} width={ANATOMY.LIMB_WIDTH_CALF} 
                variant="limb-tapered" showOverlay={showOverlay} 
                offset={offsets[sKey]} visible={visibility[sKey]} 
                partCategory={getPartCategory(sKey)} renderMode={renderMode}
              >
                <PartWrapper part={aKey}>
                  <Bone 
                    isSelected={selectedParts[aKey]} 
                    constraint={jointModes[aKey]} 
                    rotation={getTotalRotation(aKey, pose)} 
                    length={ANATOMY.FOOT} width={ANATOMY.FOOT_WIDTH} 
                    variant="hand-foot-arrowhead-shape" showOverlay={showOverlay} 
                    offset={offsets[aKey]} visible={visibility[aKey]} 
                    partCategory={getPartCategory(aKey)} renderMode={renderMode}
                  />
                </PartWrapper>
              </Bone>
            </PartWrapper>
          </Bone>
        </PartWrapper>
      </g>
    );
  };

  return (
    <g className={`mannequin-root ${className}`} transform={`translate(${pose.root.x}, ${pose.root.y}) rotate(${bodyRotation})`}>
      {/* 1. BACK LIMBS: Only rendered if not in neutral front pose */}
      {!isNeutralFront && (isRotatingRight ? renderArm(true) : renderArm(false))}
      {!isNeutralFront && (isRotatingRight ? renderLeg(true) : renderLeg(false))}

      {/* 2. CORE (Pelvis -> Torso -> Collar -> Head) */}
      <PartWrapper part={PartName.Waist}>
        <Bone 
          isSelected={selectedParts[PartName.Waist]} 
          constraint={jointModes[PartName.Waist]} 
          rotation={getTotalRotation(PartName.Waist, pose)} 
          length={ANATOMY.WAIST} width={ANATOMY.WAIST_WIDTH} 
          variant="pelvic-plate" drawsUpwards showOverlay={showOverlay} 
          offset={offsets[PartName.Waist]} visible={visibility[PartName.Waist]} 
          partCategory={getPartCategory(PartName.Waist)} renderMode={renderMode}
        >
          <PartWrapper part={PartName.Torso}>
            <Bone 
              isSelected={selectedParts[PartName.Torso]} 
              constraint={jointModes[PartName.Torso]} 
              rotation={getTotalRotation(PartName.Torso, pose)} 
              length={ANATOMY.TORSO} width={ANATOMY.TORSO_WIDTH} 
              variant="torso-teardrop-pointy-down" drawsUpwards showOverlay={showOverlay} 
              offset={offsets[PartName.Torso]} visible={visibility[PartName.Torso]} 
              partCategory={getPartCategory(PartName.Torso)} renderMode={renderMode}
            >
              <PartWrapper part={PartName.Collar}>
                <Bone 
                  isSelected={selectedParts[PartName.Collar]} 
                  constraint={jointModes[PartName.Collar]} 
                  rotation={collarRotation} 
                  length={ANATOMY.COLLAR} width={ANATOMY.COLLAR_WIDTH} 
                  variant="collar-shrug-bridge" drawsUpwards showOverlay={showOverlay} 
                  partCategory={getPartCategory(PartName.Collar)}
                  offset={offsets[PartName.Collar]} visible={visibility[PartName.Collar]} renderMode={renderMode}
                >
                  <PartWrapper part={PartName.Head}>
                    <Bone 
                      isSelected={selectedParts[PartName.Head]} 
                      constraint={jointModes[PartName.Head]} 
                      rotation={getTotalRotation(PartName.Head, pose)} 
                      length={ANATOMY.HEAD} width={ANATOMY.HEAD_WIDTH} 
                      variant="head-tall-oval" drawsUpwards showOverlay={showOverlay} 
                      offset={offsets[PartName.Head]} visible={visibility[PartName.Head]} 
                      partCategory={getPartCategory(PartName.Head)} renderMode={renderMode}
                    />
                  </PartWrapper>
                </Bone>
              </PartWrapper>
            </Bone>
          </PartWrapper>
        </Bone>
      </PartWrapper>

      {/* 3. FRONT LIMBS */}
      {isNeutralFront ? (
        <>
          {renderLeg(true)}
          {renderLeg(false)}
          {renderArm(true)}
          {renderArm(false)}
        </>
      ) : (
        <>
          {isRotatingRight ? renderLeg(false) : renderLeg(true)}
          {isRotatingRight ? renderArm(false) : renderArm(true)}
        </>
      )}

      {/* 4. ROOT ANCHOR (Standard Red Anchor) */}
      <g 
        onMouseDown={onMouseDownOnRoot} 
        onDoubleClick={(e) => { e.stopPropagation(); onToggleCrane(); }} 
        className={isCraneActive ? 'cursor-ns-resize' : 'cursor-pointer'} 
        data-no-export={true}
      >
        <circle 
          cx="0" cy="0" r={isCraneActive ? 7 : 5} 
          fill={ANCHOR_RED} 
        />
        {pin !== 'root' && joints[pin as keyof typeof joints] && (
          <g transform={`translate(${joints[pin as keyof typeof joints].x - pose.root.x}, ${joints[pin as keyof typeof joints].y - pose.root.y})`}>
            <circle cx="0" cy="0" r="5" fill={ANCHOR_RED} />
          </g>
        )}
      </g>
    </g>
  );
};

